Commit:     welpy-cw <h.w.forms@arcor.de>
CommitDate: Mon Sep 2 18:42:29 2024 +0000

    Bug 1915255 - Avoid asking for delete confirmation twice. r=mkmelin


    If `about:message` inside `about:3pane` had focus, shift-deleting, deleting from trash, or
    deleting a news message showed the confirmation dialog twice.

    Differential Revision: https://phabricator.services.mozilla.com/D220376

diff --git a/mail/base/content/mailCommon.js b/mail/base/content/mailCommon.js
index b5428c30799..c6c27e3fc3a 100644
--- a/mail/base/content/mailCommon.js
+++ b/mail/base/content/mailCommon.js
@@ -285,28 +285,28 @@ var commandController = {
       }
     },
     cmd_deleteMessage() {
-      if (!MailUtils.confirmDelete(false, gDBView, gFolder)) {
-        return;
-      }
       if (parent.location.href == "about:3pane") {
         // If we're in about:message inside about:3pane, it's the parent
         // window that needs to advance to the next message.
         parent.commandController.doCommand("cmd_deleteMessage");
         return;
       }
+      if (!MailUtils.confirmDelete(false, gDBView, gFolder)) {
+        return;
+      }
       dbViewWrapperListener.threadPaneCommandUpdater.updateNextMessageAfterDelete();
       gViewWrapper.dbView.doCommand(Ci.nsMsgViewCommandType.deleteMsg);
     },
     cmd_shiftDeleteMessage() {
-      if (!MailUtils.confirmDelete(true, gDBView, gFolder)) {
-        return;
-      }
       if (parent.location.href == "about:3pane") {
         // If we're in about:message inside about:3pane, it's the parent
         // window that needs to advance to the next message.
         parent.commandController.doCommand("cmd_shiftDeleteMessage");
         return;
       }
+      if (!MailUtils.confirmDelete(true, gDBView, gFolder)) {
+        return;
+      }
       dbViewWrapperListener.threadPaneCommandUpdater.updateNextMessageAfterDelete();
       gViewWrapper.dbView.doCommand(Ci.nsMsgViewCommandType.deleteNoTrash);
     },
diff --git a/mail/test/browser/folder-display/browser_messageCommands.js b/mail/test/browser/folder-display/browser_messageCommands.js
index b8d6cfe112c..4becf71f5b6 100644
--- a/mail/test/browser/folder-display/browser_messageCommands.js
+++ b/mail/test/browser/folder-display/browser_messageCommands.js
@@ -70,7 +70,7 @@ add_setup(async function () {
   ]);

   await make_message_sets_in_folders([unreadFolder], [{ count: 2 }]);
-  await make_message_sets_in_folders([shiftDeleteFolder], [{ count: 3 }]);
+  await make_message_sets_in_folders([shiftDeleteFolder], [{ count: 4 }]);
   await add_message_sets_to_folders(
     [threadDeleteFolder],
     [create_thread(3), create_thread(3), create_thread(3)]
@@ -498,6 +498,15 @@ add_task(async function test_shift_delete_prompt() {
   // Make sure we really did delete the message.
   Assert.notEqual(curMessage, await select_click_row(0));

+  // Third, focus the message pane, then try shift-deleting and accepting
+  // the deletion.
+  EventUtils.synthesizeKey("KEY_F6", {});
+  dialogPromise = promise_and_check_alert_dialog("accept", warning);
+  await press_delete(window, { shiftKey: true });
+  await dialogPromise;
+  // Make sure we really did delete the message.
+  Assert.notEqual(curMessage, await select_click_row(0));
+
   // Finally, try shift-deleting when we turned off the prompt.
   Services.prefs.setBoolPref("mail.warn_on_shift_delete", false);
   curMessage = await select_click_row(0);
